import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { createFlowProposalMessages, validateGeneratedFlowProposal, } from '@feltdb/core';
const CONFIG_FILE = '.feltdb/ai.json';
const SERVICE = 'feltdb-ai';
function credentialId(cwd, provider) {
    return `${createHash('sha256').update(path.resolve(cwd)).digest('hex').slice(0, 16)}:${provider}`;
}
export function readAiModelConfiguration(cwd = process.cwd()) {
    const file = path.join(cwd, CONFIG_FILE);
    if (!fs.existsSync(file))
        return { version: 1, provider: 'local-webllm', model: 'SmolLM2-360M-Instruct-q4f32_1-MLC' };
    const value = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (value.version !== 1 || !['local-webllm', 'openai-compatible'].includes(value.provider) || !value.model) {
        throw new Error(`${CONFIG_FILE} contains an unsupported AI model configuration`);
    }
    return value;
}
function storeCredential(id, secret) {
    if (process.platform === 'darwin') {
        const result = spawnSync('security', ['add-generic-password', '-U', '-s', SERVICE, '-a', id, '-w', secret], { encoding: 'utf8' });
        if (result.status !== 0)
            throw new Error(`Could not store the model credential in macOS Keychain: ${result.stderr.trim()}`);
        return;
    }
    if (process.platform === 'linux') {
        const result = spawnSync('secret-tool', ['store', '--label', 'FeltDB AI model credential', 'service', SERVICE, 'account', id], { input: secret, encoding: 'utf8' });
        if (result.status !== 0)
            throw new Error('Could not store the model credential with Secret Service. Install libsecret tools or use FELTDB_AI_API_KEY per session.');
        return;
    }
    throw new Error('Persistent AI credentials require macOS Keychain or Linux Secret Service. Use FELTDB_AI_API_KEY per session on this platform.');
}
function loadCredential(id) {
    if (process.env.FELTDB_AI_API_KEY)
        return process.env.FELTDB_AI_API_KEY;
    if (process.platform === 'darwin') {
        const result = spawnSync('security', ['find-generic-password', '-s', SERVICE, '-a', id, '-w'], { encoding: 'utf8' });
        return result.status === 0 ? result.stdout.trim() : undefined;
    }
    if (process.platform === 'linux') {
        const result = spawnSync('secret-tool', ['lookup', 'service', SERVICE, 'account', id], { encoding: 'utf8' });
        return result.status === 0 ? result.stdout.trim() : undefined;
    }
    return undefined;
}
export function configureAiModel(input, cwd = process.cwd()) {
    const id = input.provider === 'openai-compatible' ? credentialId(cwd, input.provider) : undefined;
    if (input.apiKey && id)
        storeCredential(id, input.apiKey);
    const config = { version: 1, provider: input.provider, model: input.model,
        baseUrl: input.baseUrl?.replace(/\/+$/, ''), credentialId: id,
        credentialRequired: input.provider === 'openai-compatible' ? input.credentialRequired !== false : false };
    fs.mkdirSync(path.join(cwd, '.feltdb'), { recursive: true });
    fs.writeFileSync(path.join(cwd, CONFIG_FILE), `${JSON.stringify(config, null, 2)}\n`, { mode: 0o600 });
    return config;
}
export function publicAiModelConfiguration(cwd = process.cwd()) {
    const config = readAiModelConfiguration(cwd);
    return { provider: config.provider, model: config.model, baseUrl: config.baseUrl,
        local: config.provider === 'local-webllm', credentialRequired: config.credentialRequired !== false,
        credentialConfigured: config.provider === 'local-webllm' || config.credentialRequired === false || Boolean(config.credentialId && loadCredential(config.credentialId)) };
}
export async function generateConfiguredFlowProposal(input, cwd = process.cwd()) {
    const config = readAiModelConfiguration(cwd);
    if (config.provider === 'local-webllm')
        throw new Error('Local WebLLM generation runs in the browser');
    const apiKey = config.credentialId ? loadCredential(config.credentialId) : process.env.FELTDB_AI_API_KEY;
    const baseUrl = config.baseUrl || 'https://api.openai.com/v1';
    const messages = await createFlowProposalMessages(input.snapshot, input.currentFlow, input.intent);
    const complete = async (requestMessages) => {
        const response = await fetch(`${baseUrl}/chat/completions`, {
            method: 'POST',
            headers: { 'content-type': 'application/json', ...(apiKey ? { authorization: `Bearer ${apiKey}` } : {}) },
            body: JSON.stringify({ model: config.model, messages: requestMessages, temperature: 0.1, response_format: { type: 'json_object' } }),
        });
        const body = await response.json().catch(() => ({}));
        if (!response.ok)
            throw new Error(`Configured model request failed (${response.status}): ${body.error?.message || body.error || 'unknown error'}`);
        const raw = body.choices?.[0]?.message?.content;
        if (typeof raw !== 'string')
            throw new Error('Configured model returned no proposal content');
        return raw;
    };
    const raw = await complete(messages);
    try {
        return await validateGeneratedFlowProposal({ raw, intent: input.intent, snapshot: input.snapshot, currentFlow: input.currentFlow });
    }
    catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        const repaired = await complete([...messages, { role: 'assistant', content: raw }, { role: 'user',
                content: `FeltDB rejected that proposal: ${reason}. Return one corrected complete JSON proposal. Do not broaden or add unrelated changes.` }]);
        return validateGeneratedFlowProposal({ raw: repaired, intent: input.intent, snapshot: input.snapshot, currentFlow: input.currentFlow });
    }
}
